bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || { echo STK_POLL_DOWN; exit 61; }
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';import{readFileSync}from'node:fs';
const e=process.env;
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,database:e.VIDEOBOT_DB_NAME,user:e.VIDEOBOT_DB_USER,password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1,connectionTimeoutMillis:5000});
try{
 const states=await pool.query("SELECT state->>'screen' AS screen,count(*)::int AS n FROM videobot_creator_sessions GROUP BY 1 ORDER BY 2 DESC LIMIT 20");
 console.log('STK_DM_SCREEN_AGGREGATE='+JSON.stringify(states.rows));
 const product=await pool.query("SELECT p.status AS product_status,p.price_stars,t.status AS post_status,t.message_thread_id,t.telegram_message_id,COALESCE(jsonb_array_length(p.items),0) AS item_count FROM videobot_sticker_products p JOIN videobot_sticker_topic_posts t ON t.product_id=p.product_id WHERE p.product_id=$1",['sp_76f23430d1c29ca355960a95']);
 console.log('STK_PRODUCT_READBACK='+JSON.stringify(product.rows));
 console.log('STK_SHOP_PUBLIC_URL_CONFIGURED='+Boolean(e.VIDEOBOT_SHOP_PUBLIC_URL));
}finally{await pool.end();}
NODE
docker logs --tail 220 "$name" 2>&1 | grep -E '^(CREATOR_DM_POLL_READY|CREATOR_GATE_PUBLIC_RELEASE|CREATOR_DM_UPDATES_HANDLED|STICKER_SHOP_HTTP_READY)=' | tail -n 12 || true
echo STK_READ_ONLY_DIAGNOSTIC=PASS
